@spec gm_at_member_spec  src=tests/specs/gm_at_member_spec.lua  loc=57  cases=2
@exercises groupManager (gm), midiManager (h.fm), trackerManager (h.tm)
@surface   gm:markGroup, gm:newInstance, fm:dump, tm:byUuid
@harness   mk{seed.evType, seed.chan, seed.ppq, seed.shape, seed.val, seed.ccs}

# Intent
  channel aftertouch (`at`) as a first-class gm member. Unlike pb, at has
  no detune realisation frame -- its `val` IS the intent -- so it rides the
  fully generic seams (no special makeEntry/toGroup arm) with stream identity
  `at:0`. These pins would fire if someone grew an at-specific branch that
  dropped its val or uuid. See design/archive/fx-freeze.md § pb/at as
  first-class gm members.

# Helpers
  @fn rect()  @ 11-12

# Cases
  @case 'at member: toGroup carries val verbatim (no cents rewrite)'  [pure]  @ 16-31
  @case 'at member: uuid survives the rebuild so gm can re-anchor it (tm:byUuid)'  [harness]  @ 35-55

# Uses (outbound edges)
  @use call gm:markGroup  @ 23
  @use call gm:newInstance  @ 25
  @use call fm:dump  @ 46
  @use call tm:byUuid  @ 51

